CREATE Proc [dbo].[ReportItemStokKitchen] @Date as datetime,  @ItemId as text, @BRId as int, @Adj as int = null  as  Declare @SId as int; Select @SId = Sid from Store where CentarlStore = 1 Declare @ReportName as nvarchar(max); set @ReportName='Department Wise Stock By Items'; select  CONVERT(VARCHAR(11),@Date,106) as DateFrom, U.Unit ,@ReportName as ReportName, iu.IssFactor as UnitQty, (select Unit from Unit where UId = iu.RecpUnit) as Store, c.Category,sc.Subcategory,i.Item, isnull ( (Select isnull(sum(Qty),0) from WareHouse_Branch wh where [Type]='In'and wh.ItemId=i.ItemId and Date <= @Date  and BRId = @BRId and DId = d.id) - (Select isnull(sum(Qty),0) from WareHouse_Branch wh where [Type]='Out'and wh.ItemId=i.ItemId and Date <= @Date  and BRId = @BRId and DId = d.id) ,0) as Balance, Cast(isnull(Round((select round(isnull((Rate),0),2) from WareHouse_Branch wh where [Type]='In'and id = (select max(id) from WareHouse_Branch where ItemId=i.ItemId and Date <= @Date  and BRId = @BRId and DId = d.id and [Desc] <> 'Sale')) /(select isnull(IssFactor,0) from ItemUnit where ItemId=i.ItemId),2),0) AS DECIMAL (18,2))  as Rate,d.department_name as Company,iu.RecpFactor as Parlevel  from WareHouse_Branch wh inner join Branch s on wh.BRId=s.BRId inner join DepartmentPos d on s.BRId = d.BRId inner join Item i on wh.ItemId=i.ItemId inner join Subcategory sc on i.SBId = sc.SBId inner join Category c on sc.CId=c.CId inner join ItemUnit iu on i.ItemId=iu.ItemId inner join Unit U on iu.IssUnit=U.UId inner join Split(@ItemId,',') sp on sp.items = i.ItemId where wh.Date <= @Date  and wh.BRId=@BRId and wh.DId = d.id and (wh.InvAdjId = @Adj or @Adj is null) group by U.Unit,I.ItemId,iu.RecpFactor,s.Branch, c.Category,sc.Subcategory, i.Item,d.department_name,wh.DId,d.id,iu.IssFactor,iu.RecpUnit